//! Stubs for `packages/pyright-internal/src/analyzer/typePrinter.ts`, generated by tools/stubgen.
//! Every body is `todo!()`. Port each one from the TypeScript at its marker.
//! Evaluator code: allocate with `P::new_eval` (docs/porting.md, "memory").
#![allow(
    unused_variables,
    unused_imports,
    dead_code,
    non_camel_case_types,
    clippy::all
)]

use crate::{analyzer, common, parser};
use crate::analyzer::types::{ClassType, FunctionType, Type, TypeVarType, UnionType};
use crate::common::config_options::ConfigOptions;
use jsrt::{JsMap, P, flag_ops};

// analyzer/typePrinter.ts:54
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
#[derive(jsrt::Trace)]
pub struct PrintTypeFlags(pub u32);

impl PrintTypeFlags {
    pub const None: PrintTypeFlags = PrintTypeFlags(0);
    pub const PrintUnknownWithAny: PrintTypeFlags = PrintTypeFlags(1);
    pub const OmitTypeArgsIfUnknown: PrintTypeFlags = PrintTypeFlags(2);
    pub const OmitUnannotatedParamType: PrintTypeFlags = PrintTypeFlags(4);
    pub const PEP604: PrintTypeFlags = PrintTypeFlags(8);
    pub const ParenthesizeUnion: PrintTypeFlags = PrintTypeFlags(0x10);
    pub const ExpandTypeAlias: PrintTypeFlags = PrintTypeFlags(0x20);
    pub const OmitConditionalConstraint: PrintTypeFlags = PrintTypeFlags(0x40);
    pub const ParenthesizeCallable: PrintTypeFlags = PrintTypeFlags(0x80);
    pub const PythonSyntax: PrintTypeFlags = PrintTypeFlags(0x100);
    pub const UseTypingUnpack: PrintTypeFlags = PrintTypeFlags(0x200);
    pub const ExpandTypedDictArgs: PrintTypeFlags = PrintTypeFlags(0x400);
    pub const PrintTypeVarVariance: PrintTypeFlags = PrintTypeFlags(0x800);
    pub const UseFullyQualifiedNames: PrintTypeFlags = PrintTypeFlags(0x1000);
    pub const OmitTypeVarScope: PrintTypeFlags = PrintTypeFlags(0x2000);
}

flag_ops!(PrintTypeFlags);

// analyzer/typePrinter.ts:106
pub fn print_type(
    type_: P<Type>,
    print_type_flags: PrintTypeFlags,
    return_type_callback: P<dyn FunctionReturnTypeCallback>,
) -> String {
    let mut unique_name_map = UniqueNameMap::new(print_type_flags, return_type_callback.clone());
    unique_name_map.build(type_, &mut Vec::new(), 0);

    print_type_internal(
        type_,
        print_type_flags,
        return_type_callback,
        &mut unique_name_map,
        &mut Vec::new(),
        0,
    )
}

// analyzer/typePrinter.ts:117
pub fn print_function_parts(
    type_: FunctionType,
    print_type_flags: PrintTypeFlags,
    return_type_callback: P<dyn FunctionReturnTypeCallback>,
) -> (Vec<String>, String) {
    let mut unique_name_map = UniqueNameMap::new(print_type_flags, return_type_callback.clone());
    unique_name_map.build(type_.0, &mut Vec::new(), 0);

    print_function_parts_internal(
        type_,
        print_type_flags,
        return_type_callback,
        &mut unique_name_map,
        &mut Vec::new(),
        0,
    )
}

